package com.turboio.androidtests;
import android.app.*;import android.content.*;import android.os.*;import java.io.*;import java.lang.reflect.*;import java.nio.charset.StandardCharsets;import org.json.*;

/** One read of the original daily journal; outputs counts and contract booleans only. */
public final class DailySummaryContractProbe extends Instrumentation {
 private Bundle args;public void onCreate(Bundle b){super.onCreate(b);args=b;start();}
 public void onStart(){Bundle result=new Bundle();Object transport=null;try{String nonce=args.getString("probe_id","");if(!nonce.matches("[a-f0-9]{32}"))throw new IllegalArgumentException();Context app=getTargetContext();ClassLoader loader=app.getClassLoader();Class<?> login=loader.loadClass("com.turboio.addon.Host107Login");Method current=login.getDeclaredMethod("account");current.setAccessible(true);app.startActivity(new Intent().setClassName(app,"com.rayneo.venus.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Object account=null;for(int i=0;i<40&&account==null;i++){account=current.invoke(null);if(account==null)Thread.sleep(250);}if(account==null)throw new IOException("OFFICIAL_LOGIN_REQUIRED");Class<?> guard=loader.loadClass("com.turboio.addon.MaterialSyncSession$Guard"),type=loader.loadClass("com.turboio.addon.Host107LifelogHttp");Constructor<?> ctor=type.getDeclaredConstructor(Context.class,account.getClass(),guard);ctor.setAccessible(true);transport=ctor.newInstance(app,account,Proxy.newProxyInstance(loader,new Class<?>[]{guard},(p,m,v)->null));Method get=type.getDeclaredMethod("get",String.class);get.setAccessible(true);byte[] bytes=(byte[])get.invoke(transport,"/lifelog/api/v1/journal/latest");JSONObject root=new JSONObject(new String(bytes,StandardCharsets.UTF_8));JSONArray rows=root.getJSONArray("data");int daily=0;boolean same=true;for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if("daily".equals(row.optString("periodType"))){daily++;same&=row.optString("periodStart").equals(row.optString("periodEnd"));}}
 Class<?> parser=getClass().getClassLoader().loadClass("com.turboio.androidtests.voice.DailySummary");Method parse=parser.getDeclaredMethod("latest",byte[].class);parse.setAccessible(true);java.util.List<?> summaries=(java.util.List<?>)parse.invoke(null,bytes);
 JSONObject report=new JSONObject().put("schema",1).put("probe_id",nonce).put("read_only",true).put("network_requests",1).put("text_or_identifiers_exported",false).put("daily_count",daily).put("parsed_daily_count",summaries.size()).put("same_day_boundaries",same);try(FileOutputStream out=new FileOutputStream(new File(app.getExternalFilesDir(null),"io-agent-daily-summary-contract.json"))){out.write(report.toString().getBytes(StandardCharsets.UTF_8));out.getFD().sync();}result.putBoolean("passed",true);finish(Activity.RESULT_OK,result);
 }catch(Throwable error){while(error.getCause()!=null)error=error.getCause();String message=error.getMessage();result.putString("error",message!=null&&message.matches("[A-Z_]{3,80}")?message:error.getClass().getSimpleName());finish(Activity.RESULT_CANCELED,result);}finally{if(transport!=null)try{Method close=transport.getClass().getDeclaredMethod("close");close.setAccessible(true);close.invoke(transport);}catch(Exception ignored){}}}
}
